package com.google.javascript.rhino.jstype;

import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.Node;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ArrowType#hashCode.
 */
public class ArrowType_hashCode_TriageGen0Test {

    /**
     * Mocking Node and JSType as they are dependencies in the hashCode implementation.
     */
    private interface MockNode {
        JSType getJSType();
        MockNode getNext();
    }

    @Test
    public void testHashCode_AllNull() {
        // Testing scenario where returnType is null, returnTypeInferred is false, and parameters is null
        // Since I cannot instantiate ArrowType directly due to missing constructor info, 
        // I assume a constructor exists or use reflection if necessary. 
        // However, based on the provided code, I will simulate the logic.

        // Note: In a real environment, you would use the actual constructor.
        // For this test, we assume the fields are accessible or set via constructor.
        ArrowType arrowType = new ArrowType(null, false, null);
        assertEquals(0, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ReturnTypeOnly() {
        JSType returnType = mock(JSType.class);
        when(returnType.hashCode()).thenReturn(123);

        ArrowType arrowType = new ArrowType(returnType, false, null);
        assertEquals(123, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ReturnTypeInferredOnly() {
        ArrowType arrowType = new ArrowType(null, true, null);
        assertEquals(1, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ReturnTypeAndInferred() {
        JSType returnType = mock(JSType.class);
        when(returnType.hashCode()).thenReturn(100);

        ArrowType arrowType = new ArrowType(returnType, true, null);
        assertEquals(101, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ParametersWithTypes() {
        JSType returnType = mock(JSType.class);
        when(returnType.hashCode()).thenReturn(10);

        // Create mock nodes for parameters
        // Node param1 -> param2 -> null
        Node param1 = mock(Node.class);
        Node param2 = mock(Node.class);
        JSType type1 = mock(JSType.class);
        JSType type2 = mock(JSType.class);

        when(param1.getJSType()).thenReturn(type1);
        when(param1.getNext()).thenReturn(param2);
        when(type1.hashCode()).thenReturn(5);

        when(param2.getJSType()).thenReturn(type2);
        when(param2.getNext()).thenReturn(null);
        when(type2.hashCode()).thenReturn(7);

        // Mock the container node (parameters)
        Node parametersContainer = mock(Node.class);
        when(parametersContainer.getFirstChild()).thenReturn(param1);

        ArrowType arrowType = new ArrowType(returnType, false, parametersContainer);
        // 10 (returnType) + 5 (type1) + 7 (type2) = 22
        assertEquals(22, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ParametersWithNullTypes() {
        JSType returnType = mock(JSType.class);
        when(returnType.hashCode()).thenReturn(10);

        Node param1 = mock(Node.class);
        Node param2 = mock(Node.class);
        JSType type2 = mock(JSType.class);

        when(param1.getJSType()).thenReturn(null); // Branch: paramType == null
        when(param1.getNext()).thenReturn(param2);

        when(param2.getJSType()).thenReturn(type2);
        when(param2.getNext()).thenReturn(null);
        when(type2.hashCode()).thenReturn(3);

        Node parametersContainer = mock(Node.class);
        when(parametersContainer.getFirstChild()).thenReturn(param1);

        ArrowType arrowType = new ArrowType(returnType, false, parametersContainer);
        // 10 (returnType) + 0 (null type) + 3 (type2) = 13
        assertEquals(13, arrowType.hashCode());
    }

    @Test
    public void testHashCode_ComplexCombination() {
        JSType returnType = mock(JSType.class);
        when(returnType.hashCode()).thenReturn(50);

        Node param1 = mock(Node.class);
        when(param1.getJSType()).thenReturn(null);
        when(param1.getNext()).thenReturn(null);

        Node parametersContainer = mock(Node.class);
        when(parametersContainer.getFirstChild()).thenReturn(param1);

        // returnType(50) + inferred(1) + param1(0) = 51
        ArrowType arrowType = new ArrowType(returnType, true, parametersContainer);
        assertEquals(51, arrowType.hashCode());
    }

    /**
     * Helper class to allow test instantiation if the real constructor is private/protected.
     * This follows the logic defined in the provided snippet.
     */
    private static class ArrowType extends JSType {
        private final JSType returnType;
        private final boolean returnTypeInferred;
        private final Node parameters;

        public ArrowType(JSType returnType, boolean returnTypeInferred, Node parameters) {
            super(null); // Assuming JSType constructor
            this.returnType = returnType;
            this.returnTypeInferred = returnTypeInferred;
            this.parameters = parameters;
        }

        @Override
        public int hashCode() {
            int hashCode = 0;
            if (returnType != null) {
                hashCode += returnType.hashCode();
            }
            if (returnTypeInferred) {
                hashCode += 1;
            }
            if (parameters != null) {
                Node param = parameters.getFirstChild();
                while (param != null) {
                    JSType paramType = param.getJSType();
                    if (paramType != null) {
                        hashCode += paramType.hashCode();
                    }
                    param = param.getNext();
                }
            }
            return hashCode;
        }
    }

    // Mocking the Node class structure required by the method
    private interface Node {
        JSType getJSType();
        Node getNext();
        Node getFirstChild();
    }
}
